// Alembic - migration runner demo
var migrations = [
  { v: 1, up: "CREATE TABLE users(id INT)", down: "DROP TABLE users" },
  { v: 2, up: "ALTER TABLE users ADD COLUMN email TEXT", down: "ALTER TABLE users DROP COLUMN email" }
];
var applied = [];
console.log("Tool: Alembic | Strategy: versioned scripts");
migrations.forEach(function(m) { applied.push(m.v); console.log("  apply v" + m.v + ": " + m.up); });
console.log("Schema at v" + applied[applied.length - 1]);
var last = migrations.pop();
console.log("  rollback v" + last.v + ": " + last.down + " -> downgrade revisions");
console.log("Migrations applied + rolled back -> PASS");

